// components/pages/Report.js - With search and date filters
import React, { useState, useEffect, useCallback } from 'react';
import { apiCall, escapeHtml, normalizePhone } from '../../utils/api';

const Report = ({ currentUserRole }) => {
  const [reportType, setReportType] = useState('Line');
  const [allData, setAllData] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchType, setSearchType] = useState('all');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const loadData = useCallback(async () => {
    setLoading(true);
    if (reportType === 'Line') {
      const result = await apiCall('getLines');
      if (result.success) {
        setAllData(result.lines || []);
        setFilteredData(result.lines || []);
      }
    } else {
      const [tillsResult, linesResult] = await Promise.all([
        apiCall('getTills'),
        apiCall('getLines')
      ]);
      
      if (tillsResult.success) {
        const lines = linesResult.lines || [];
        const lineMap = new Map();
        lines.forEach(line => {
          const normalizedPhone = normalizePhone(line.phone);
          lineMap.set(normalizedPhone, line);
        });
        
        const formattedData = (tillsResult.tills || []).map(t => {
          const ownerLine = lineMap.get(normalizePhone(t.phone || ''));
          return {
            ...t,
            ownerPhone: ownerLine ? ownerLine.phone : (t.phone || '-')
          };
        });
        setAllData(formattedData);
        setFilteredData(formattedData);
      }
    }
    setLoading(false);
  }, [reportType]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const safeToString = (value) => {
    if (value === null || value === undefined) return '';
    return String(value).toLowerCase();
  };

  const handleSearch = () => {
    const term = searchTerm.toLowerCase().trim();
    let filtered = [...allData];

    // Filter by search term
    if (term) {
      filtered = filtered.filter(item => {
        if (reportType === 'Line') {
          const fields = {
            name: safeToString(item.name),
            idNumber: safeToString(item.idNumber),
            phone: safeToString(item.phone),
            dob: safeToString(item.dob)
          };
          if (searchType === 'all') {
            return Object.values(fields).some(f => f.includes(term));
          }
          return fields[searchType]?.includes(term) || false;
        } else {
          const fields = {
            name: safeToString(item.name),
            tillNumber: safeToString(item.tillNumber),
            storeNumber: safeToString(item.storeNumber),
            phone: safeToString(item.phone),
            operatorId: safeToString(item.operatorId)
          };
          if (searchType === 'all') {
            return Object.values(fields).some(f => f.includes(term));
          }
          return fields[searchType]?.includes(term) || false;
        }
      });
    }

    // Filter by date range
    if (startDate || endDate) {
      filtered = filtered.filter(item => {
        const itemDate = item.dateCreated ? new Date(item.dateCreated) : null;
        if (!itemDate) return false;
        
        if (startDate && endDate) {
          const start = new Date(startDate);
          const end = new Date(endDate);
          end.setHours(23, 59, 59, 999);
          return itemDate >= start && itemDate <= end;
        } else if (startDate) {
          const start = new Date(startDate);
          return itemDate >= start;
        } else if (endDate) {
          const end = new Date(endDate);
          end.setHours(23, 59, 59, 999);
          return itemDate <= end;
        }
        return true;
      });
    }

    setFilteredData(filtered);
    if (filtered.length === 0 && (term || startDate || endDate)) {
      // Don't show toast for date filters to avoid spam
      if (term) {
        // Toast only for search term
      }
    }
  };

  const handleClearFilters = () => {
    setSearchTerm('');
    setSearchType('all');
    setStartDate('');
    setEndDate('');
    setFilteredData(allData);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <i className="fas fa-spinner fa-pulse"></i> Loading report...
      </div>
    );
  }

  const renderTable = () => {
    if (filteredData.length === 0) {
      return (
        <div className="empty-state">
          <i className="fas fa-inbox"></i>
          <br />No {reportType === 'Line' ? 'lines' : 'tills'} found matching your filters
        </div>
      );
    }

    if (reportType === 'Line') {
      return (
        <div className="table-wrapper">
          <table className="modern-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>ID Number</th>
                <th>Phone</th>
                <th>DOB</th>
                <th>Date Created</th>
              </tr>
            </thead>
            <tbody>
              {filteredData.map((line, index) => (
                <tr key={index}>
                  <td><strong>{escapeHtml(line.name || '-')}</strong></td>
                  <td>{escapeHtml(line.idNumber || '-')}</td>
                  <td><i className="fas fa-phone"></i> {escapeHtml(line.phone || '-')}</td>
                  <td>{escapeHtml(line.dob || '-')}</td>
                  <td>{line.dateCreated ? new Date(line.dateCreated).toLocaleDateString() : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    } else {
      return (
        <div className="table-wrapper">
          <table className="modern-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Owner Phone</th>
                <th>Till Number</th>
                <th>Store</th>
                <th>Units</th>
                <th>Status</th>
                <th>Date Created</th>
              </tr>
            </thead>
            <tbody>
              {filteredData.map((till, index) => (
                <tr key={index}>
                  <td><strong>{escapeHtml(till.name || '-')}</strong></td>
                  <td>{escapeHtml(till.ownerPhone)}</td>
                  <td><span className="till-badge">{escapeHtml(till.tillNumber || '-')}</span></td>
                  <td>{escapeHtml(till.storeNumber || '-')}</td>
                  <td><span className="units-black">{till.units || 0} units</span></td>
                  <td>
                    <span className={`badge ${till.status === 'active' ? 'badge-success' : 'badge-danger'}`}>
                      {till.status === 'active' ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td>{till.dateCreated ? new Date(till.dateCreated).toLocaleDateString() : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }
  };

  const getSearchFields = () => {
    if (reportType === 'Line') {
      return [
        { value: 'all', label: 'All Fields' },
        { value: 'name', label: 'Name' },
        { value: 'idNumber', label: 'ID Number' },
        { value: 'phone', label: 'Phone' },
        { value: 'dob', label: 'Date of Birth' }
      ];
    } else {
      return [
        { value: 'all', label: 'All Fields' },
        { value: 'name', label: 'Name' },
        { value: 'tillNumber', label: 'Till Number' },
        { value: 'storeNumber', label: 'Store' },
        { value: 'phone', label: 'Phone' },
        { value: 'operatorId', label: 'Operator ID' }
      ];
    }
  };

  return (
    <>
      <h3 className="section-title">
        <i className="fas fa-chart-line"></i> Analytics Reports
        <span className="badge-count">{filteredData.length} records</span>
      </h3>
      
      <div className="submenu">
        <button 
          className={reportType === 'Line' ? 'active' : ''}
          onClick={() => setReportType('Line')}
        >
          <i className="fas fa-users"></i> Line Report
        </button>
        <button 
          className={reportType === 'Till' ? 'active' : ''}
          onClick={() => setReportType('Till')}
        >
          <i className="fas fa-cash-register"></i> Till Report
        </button>
      </div>

      <div className="search-bar-advanced">
        <div className="search-row">
          <div className="search-input-group">
            <i className="fas fa-search search-icon"></i>
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Search records..."
              className="search-input"
            />
          </div>
          <select 
            value={searchType}
            onChange={(e) => setSearchType(e.target.value)}
            className="search-select"
          >
            {getSearchFields().map(field => (
              <option key={field.value} value={field.value}>
                {field.label}
              </option>
            ))}
          </select>
        </div>
        
        <div className="date-row">
          <div className="date-group">
            <label><i className="fas fa-calendar-alt"></i> From</label>
            <input 
              type="date" 
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="date-input"
            />
          </div>
          <div className="date-group">
            <label><i className="fas fa-calendar-alt"></i> To</label>
            <input 
              type="date" 
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="date-input"
            />
          </div>
          <div className="action-group">
            <button className="btn-search-primary" onClick={handleSearch}>
              <i className="fas fa-search"></i> Apply Filters
            </button>
            <button className="btn-secondary" onClick={handleClearFilters}>
              <i className="fas fa-undo"></i> Clear
            </button>
          </div>
        </div>
      </div>

      {renderTable()}
    </>
  );
};

export default Report;
